input.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

:root {
  /* Side margin that grows on wide screens, so the content is never wider than 1152px. */
  --page-margin: max(64px, (100% - 1152px) / 2);
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 12px 28px;
  padding: 18px var(--page-margin);
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 28px;
}

.site-nav a {
  text-decoration: none;
  color: #5c544b;
  white-space: nowrap;
}

.site-nav .nav-signin {
  color: #2a2622;
  font-weight: 500;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 64px;
  padding: 64px var(--page-margin) 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  /* Even out the line lengths, so the last line never holds one word alone. */
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #5c544b;
}

.preview {
  flex: 0 0 480px;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  display: flex;
  gap: 40px;
  padding: 8px var(--page-margin) 48px;
}

.facts p {
  flex: 1;
  margin: 0;
  color: #5c544b;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/* Phone and tablet: put the hero and the features in one column. */
@media (max-width: 900px) {
  :root {
    --page-margin: 24px;
  }

  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 40px;
    padding-top: 40px;
  }

  .hero-text {
    max-width: none;
  }

  .preview {
    flex: none;
  }

  .facts {
    flex-direction: column;
    gap: 16px;
  }
}

/* Phone: a smaller headline and narrower table cells, so the three columns fit. */
@media (max-width: 480px) {
  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 12px;
  }
}

