  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #5c544b;
}

.preview {
  flex: 0 0 480px;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  display: flex;
  gap: 40px;
  padding: 8px var(--page-margin) 48px;
}

.facts p {
  flex: 1;
  margin: 0;
  color: #5c544b;
  /* Avoid one word alone on the last line. */
  text-wrap: pretty;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/* Phone and tablet: put the hero and the features in one column. */
@media (max-width: 900px) {
  :root {
    --page-margin: 24px;
  }

  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 40px;
    padding-top: 40px;
  }

  /* Keep text lines near 550px, so they stay readable while the table uses the full width. */
  .hero-text {
    max-width: 550px;
  }

  .preview {
    flex: none;
  }

  .facts {
    flex-direction: column;
    gap: 16px;
  }

  .facts p {
    flex: none;
    max-width: 560px;
  }
}

/* Phone: a smaller headline and narrower table cells, so the three columns fit. */
@media (max-width: 480px) {
  h1 {
    font-size: 32px;
  }

  /* Keep each table row on one line. */
  th,
  td {
    padding: 9px 6px;
    white-space: nowrap;
  }

  th:first-child,
  td:first-child {
    padding-left: 12px;
  }

  th:last-child,
  td:last-child {
    padding-right: 12px;
  }

  .preview-head {
    padding: 14px 12px;
  }
}

